const item = $input.first();
const body = item.json.body || item.json;

const ticket = {
  customerId: body.customer_id || body.email || 'anonymous',
  customerName: body.name || 'Customer',
  email: body.email || '',
  channel: body.channel || 'web',
  subject: body.subject || '(no subject)',
  message: body.message || '',
  language: body.language || 'en',
  previousTickets: body.previous_tickets || 0,
  accountTier: body.account_tier || 'free',
  timestamp: new Date().toISOString(),
  ticketId: 'TKT-' + Date.now().toString(36).toUpperCase()
};

return [{ json: ticket }];

const ticket = $('Parse Ticket').first().json;
const kbResults = $('Search Knowledge Base').first().json;
const orders = $('Fetch Order History').first().json;

let kbContext = 'No relevant articles found.';
if (kbResults && kbResults.results && kbResults.results.length > 0) {
  kbContext = kbResults.results.map((r, i) => 
    `Article ${i+1}: ${r.title}\n${r.content || r.snippet || r.summary}`
  ).join('\n\n');
}

let orderContext = 'No order history available.';
if (orders && orders.orders && orders.orders.length > 0) {
  orderContext = orders.orders.map(o => 
    `Order ${o.id}: ${o.status} - ${o.items?.map(i => i.name).join(', ') || 'N/A'} ($${o.total || 'N/A'}) - ${o.date || 'N/A'}`
  ).join('\n');
}

return [{
  json: {
    ...ticket,
    kbContext,
    orderContext
  }
}];

