const ticket = $('Merge Context').first().json;
let aiResponse;

try {
  const raw = $input.first().json;
  const content = raw.message?.content || raw.choices?.[0]?.message?.content || JSON.stringify(raw);
  aiResponse = typeof content === 'string' ? JSON.parse(content) : content;
} catch (e) {
  aiResponse = {
    category: 'general',
    priority: 'medium',
    sentiment: 'neutral',
    can_resolve: false,
    response: '<p>Thank you for reaching out. Your ticket has been received and a team member will get back to you shortly.</p>',
    internal_notes: 'AI classification failed - needs manual review',
    suggested_tags: ['needs-review'],
    escalate_to: null,
    follow_up_needed: true,
    confidence: 0.0
  };
}

return [{
  json: {
    ticketId: ticket.ticketId,
    customerId: ticket.customerId,
    customerName: ticket.customerName,
    email: ticket.email,
    channel: ticket.channel,
    subject: ticket.subject,
    originalMessage: ticket.message,
    accountTier: ticket.accountTier,
    timestamp: ticket.timestamp,
    category: aiResponse.category,
    priority: aiResponse.priority,
    sentiment: aiResponse.sentiment,
    canResolve: aiResponse.can_resolve,
    response: aiResponse.response,
    internalNotes: aiResponse.internal_notes,
    suggestedTags: aiResponse.suggested_tags || [],
    escalateTo: aiResponse.escalate_to,
    followUpNeeded: aiResponse.follow_up_needed,
    confidence: aiResponse.confidence,
    resolvedAt: aiResponse.can_resolve ? new Date().toISOString() : null
  }
}];

